UPDATE truss.feed_tx t SET finalized_generation = NULL, manifest_bytes = NULL, manifest_sha256 = NULL WHERE t.source_epoch = $1::pg_catalog.text AND t.feed_profile = $2::pg_catalog.text AND t.original_writer_xid = pg_catalog.pg_current_xact_id_if_assigned() AND t.membership_generation = $3::bigint RETURNING t.source_epoch, t.feed_profile, t.original_writer_xid::pg_catalog.text AS original_writer_xid, t.membership_generation::pg_catalog.text AS membership_generation, t.finalized_generation::pg_catalog.text AS finalized_generation, pg_catalog.encode(t.manifest_bytes, 'hex') AS manifest_bytes_hex, pg_catalog.encode(t.manifest_sha256, 'hex') AS manifest_sha256_hex